import net.akehurst.kotlinx.reflect.KotlinxReflect
import kotlinx_reflect_gradle_plugin_test_commonMain.KotlinxReflectForModule
import net.akehurst.kotlinx.reflect.gradle.plugin.test.moduleForReflection.CCCC
import net.akehurst.kotlinx.reflect.reflect
import kotlin.test.*

/**
 * CCCC lives in a dependency module that applies no plugin.
 * Its registrations are generated by the KSP processor into this module's commonMain.
 */
class test_KspRegistration {

    private val qn = "net.akehurst.kotlinx.reflect.gradle.plugin.test.moduleForReflection.CCCC"

    @BeforeTest
    fun setup() {
        // use only the generated registrations, on every platform
        KotlinxReflect.forceRegistry = true
        KotlinxReflectForModule.registerUsedClasses()
    }

    @Test
    fun classForName() {
        assertEquals(CCCC::class, KotlinxReflect.classForName(qn))
        assertEquals(qn, CCCC::class.reflect().qualifiedName)
    }

    @Test
    fun construct_allArgs() {
        val obj = KotlinxReflect.classForName(qn).reflect().construct("bob", 5) as CCCC
        assertEquals("bob", obj.name)
        assertEquals(5, obj.count)
    }

    @Test
    fun construct_defaultArg() {
        val obj = KotlinxReflect.classForName(qn).reflect().construct("bob") as CCCC
        assertEquals(0, obj.count)
    }

    @Test
    fun construct_tooFewArgs() {
        val e = assertFailsWith<IllegalStateException> { KotlinxReflect.classForName(qn).reflect().construct() }
        assertEquals("No constructor with 0 parameter(s) found for class 'CCCC'", e.message)
    }

    @Test
    fun allPropertyNames() {
        assertEquals(setOf("name", "count", "description"), CCCC("bob").reflect().allPropertyNames.toSet())
    }

    @Test
    fun getProperty() {
        val obj = CCCC("bob", 2)
        assertEquals("bob", obj.reflect().getProperty("name"))
        assertEquals("bob has 2", obj.reflect().getProperty("description"))
    }

    @Test
    fun setProperty() {
        val obj = CCCC("bob")
        obj.reflect().setProperty("count", 7)
        assertEquals(7, obj.count)
    }

    @Test
    fun setProperty_val_fails() {
        val e = assertFailsWith<IllegalStateException> { CCCC("bob").reflect().setProperty("name", "x") }
        assertEquals("Property 'name' on class 'CCCC' is not mutable", e.message)
    }

    @Test
    fun isPropertyMutable() {
        assertEquals(false, CCCC::class.reflect().isPropertyMutable("name"))
        assertEquals(true, CCCC::class.reflect().isPropertyMutable("count"))
    }

    @Test
    fun call() {
        assertEquals("hello bob", CCCC("bob").reflect().call("greet", "hello"))
    }

    @Test
    fun call_defaultArg() {
        val obj = CCCC("bob")
        assertEquals(1, obj.reflect().call("increment"))
        assertEquals(6, obj.reflect().call("increment", 5))
    }

    @Test
    fun isSupertypeOf() {
        assertTrue(Any::class.reflect().isSupertypeOf(CCCC::class))
    }
}
